package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
import org.bukkit.Material;
public class InfusionSealTest {
 @Test public void compatibilitySeparatesArmorMeleeRangedAndTools(){assertTrue(RareCompatibility.accepts("durability",Material.NETHERITE_CHESTPLATE));assertFalse(RareCompatibility.accepts("durability",Material.NETHERITE_SWORD));assertTrue(RareCompatibility.accepts("veneno",Material.NETHERITE_SWORD));assertFalse(RareCompatibility.accepts("veneno",Material.NETHERITE_PICKAXE));assertFalse(RareCompatibility.accepts("veneno",Material.BOW));assertTrue(RareCompatibility.accepts("calllighting",Material.BOW));assertFalse(RareCompatibility.accepts("calllighting",Material.NETHERITE_AXE));assertTrue(RareCompatibility.accepts("veinminer",Material.NETHERITE_PICKAXE));assertFalse(RareCompatibility.accepts("veinminer",Material.NETHERITE_AXE));assertTrue(RareCompatibility.accepts("treefeller",Material.NETHERITE_AXE));assertFalse(RareCompatibility.accepts("treefeller",Material.NETHERITE_SWORD));}
 @Test public void armorSpecificPowersRemainSpecific(){assertTrue(RareCompatibility.accepts("flame",Material.DIAMOND_HELMET));assertFalse(RareCompatibility.accepts("flame",Material.DIAMOND_BOOTS));assertTrue(RareCompatibility.accepts("hardy",Material.DIAMOND_CHESTPLATE));assertFalse(RareCompatibility.accepts("hardy",Material.DIAMOND_HELMET));}
 @Test public void unlockRequiresOneSealAndASealedBossPiece(){assertTrue(RareCompatibility.blocked(true,false));assertFalse(RareCompatibility.blocked(true,true));assertFalse(RareCompatibility.blocked(false,false));assertTrue(RareCompatibility.canAwaken(true,false,1));assertFalse(RareCompatibility.canAwaken(false,false,1));assertFalse(RareCompatibility.canAwaken(true,true,1));assertFalse(RareCompatibility.canAwaken(true,false,2));assertTrue(RareCompatibility.bossGear("armadura_set_abyssal_0",false));assertTrue(RareCompatibility.bossGear("arco_ceniciento",false));assertFalse(RareCompatibility.bossGear("pvp_gear_vigia",false));assertTrue(RareCompatibility.bossGear(null,true));}
 @Test public void recipeGroupsSeparateUnlockFromOrdinaryInfusions(){assertEquals(RareCompatibility.Group.ARMOR,RareCompatibility.recipe("crear_esencia_rare_durability"));assertEquals(RareCompatibility.Group.TOOLS,RareCompatibility.recipe("crear_esencia_rare_veinminer"));assertEquals(RareCompatibility.Group.RANGED,RareCompatibility.recipe("pvp_gear_ocaso"));assertEquals(RareCompatibility.Group.UNLOCK,RareCompatibility.recipe("sello_resonancia_primigenia"));assertEquals(RaresMenu.Category.ESSENCES,RaresMenu.Category.category("sello_resonancia_primigenia"));}
}
